let LANG="en";
try{const s=localStorage.getItem("tlf-lang"); if(s&&I18N[s]) LANG=s;}catch(e){}
const loc=()=>(LANGS.find(l=>l[0]===LANG)||LANGS[0])[2];
function t(k,vars){
  let s=(I18N[LANG]&&I18N[LANG][k])??I18N.en[k]??k;
  if(vars) s=s.replace(/\{(\w+)\}/g,(_,v)=>vars[v]!=null?vars[v]:"");
  return s;
}
const fmtInt=x=>(Math.round(x)+0).toLocaleString(loc());
const fmtDec=(x,d)=>x.toLocaleString(loc(),{minimumFractionDigits:d,maximumFractionDigits:d});
